// The generated files at the top of a chat's folder (plan §5, §5.1, §4.8): `PROMPT-MAP.md`, the map of the
// preset the chat is played on as it stands, for agents and for him to read, and `LORE-INDEX.md`. RPE writes
// them and nobody else: an agent's write is refused as generated by the file port, and a page's by the
// listing's `editable`; he edits the map on the Prompt page and the file follows. This is the one writer
// every maker of such a file calls: it writes only a chat that has its folder, and only when the text is
// not what the file holds, so a file that stands as it should is not touched.
//
// The words of the file are a prompt part's (`guidance/.prompts/`), filled from the fields `promptMapFields`
// gives: the map's slices with their marker, kind, line and how each is found again and behaves, or, until a
// map is learned, the names of the raw layout's blocks.

import { mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";
import type { JsonValue, PromptMap, RawLayout } from "rp-harness/contract";
import { oneFileAtATime, readText, writeWhole } from "../app/disk";
import type { TreeChats } from "./chats";
import { CHATS_FOLDER, GENERATED_FILES } from "./layout";

export interface GeneratedDeps {
  /** The tree's folder: the global level. */
  files: string;
  chats: TreeChats;
}

/** What writing a generated file came to. */
export type GeneratedWrite = "written" | "same" | "unplaced";

export class GeneratedFiles {
  readonly #d: GeneratedDeps;

  constructor(deps: GeneratedDeps) {
    this.#d = deps;
  }

  /** Writes `text` as the generated file `name` at the top of the chat's folder, unless it holds that already. A chat RPE has not placed has no folder, so nothing is written. */
  async write(user: string, chat: string, name: string, text: string): Promise<GeneratedWrite> {
    if (!GENERATED_FILES.includes(name)) throw new Error(`${name} is not a file RPE makes at the top of a chat's folder: ${GENERATED_FILES.join(", ")}.`);
    const folders = this.#d.chats.folders(user, chat);
    if (folders === null) return "unplaced";
    const disk = join(this.#d.files, CHATS_FOLDER, folders.character, folders.chat, name);
    return await oneFileAtATime(disk, async () => {
      if ((await readText(disk)) === text) return "same";
      await mkdir(dirname(disk), { recursive: true });
      await writeWhole(disk, text);
      return "written";
    });
  }
}

/** The fields the prompt map's file is laid out from. */
export type PromptMapFields = { [name: string]: JsonValue };

/**
 * The fields of `PROMPT-MAP.md` for a chat: the preset's learned map with his edits, each slice by marker, kind, line, behaviour,
 * how it is found again and whether he edited it; and the raw layout's block names beside, which are all there is until a map is
 * learned. `learned` says which.
 */
export function promptMapFields(map: PromptMap | undefined, layout: RawLayout | null): PromptMapFields {
  const preset = map?.preset ?? layout?.preset ?? null;
  return {
    learned: map !== undefined,
    preset: preset === null ? null : { id: preset.id, ...(preset.name === undefined ? {} : { name: preset.name }), ...(preset.revision === undefined ? {} : { revision: preset.revision }) },
    slices: (map?.slices ?? []).map((s) => ({
      marker: s.marker,
      kind: s.kind,
      line: s.line,
      behaviour: s.behaviour,
      edited: s.edited === true,
      signature: s.find.signature !== undefined,
      ...(s.find.after === undefined ? {} : { after: s.find.after }),
      ...(s.find.before === undefined ? {} : { before: s.find.before }),
      ...(s.find.block === undefined ? {} : { block: s.find.block }),
    })),
    blocks: (layout?.blocks ?? []).map((b, i) => ({ n: i + 1, name: b.name, type: b.type, kind: b.kind ?? "other" })),
  };
}
